#!/usr/bin/env python3
"""app/tokens/sosed.tokens.json -> app/tokens/sosed.gen.css.

Run inside a container with -I:  python3 -I scripts/design/app-tokens.py [--check]
--check writes nothing and exits 1 when the generated file differs from the JSON.
Breakpoints (design README): sheet radius 40 mobile, 48 from 834, 36 from 1440.
"""
import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent.parent
SRC = ROOT / "app/tokens/sosed.tokens.json"
OUT = ROOT / "app/tokens/sosed.gen.css"


def kebab(name: str) -> str:
    return re.sub(r"([A-Z])", lambda m: "-" + m.group(1).lower(), name)


def render(t: dict) -> str:
    L = ["/* GENERATED by scripts/design/app-tokens.py from sosed.tokens.json. Do not edit. */", ":root {"]
    L.append("  color-scheme: dark;")
    for k, v in t["color"].items():
        if k == "avatar":
            for i, c in enumerate(v, 1):
                L.append(f"  --c-avatar-{i}: {c};")
        else:
            L.append(f"  --c-{kebab(k)}: {v};")
    L.append(f'  --font-family: "{t["font"]["family"]}";')
    for w in t["font"]["weights"]:
        L.append(f"  --fw-{w}: {w};")
    for k, v in t["radius"].items():
        L.append(f"  --r-{kebab(k)}: {v}px;")
    L.append("  --r-sheet: var(--r-sheet-mobile);")
    for k, v in t["size"].items():
        L.append(f"  --s-{kebab(k)}: {v}px;")
    L.append("}")
    L.append("@media (min-width: 834px) { :root { --r-sheet: var(--r-sheet-tablet); } }")
    L.append("@media (min-width: 1440px) { :root { --r-sheet: var(--r-panel-desktop); } }")
    return "\n".join(L) + "\n"


def main() -> int:
    want = render(json.loads(SRC.read_text()))
    if "--check" in sys.argv[1:]:
        have = OUT.read_text() if OUT.exists() else None
        if have != want:
            print("app-tokens: STALE — sosed.gen.css differs from sosed.tokens.json; run without --check", file=sys.stderr)
            return 1
        print("app-tokens: OK")
        return 0
    OUT.write_text(want)
    print(f"app-tokens: wrote {OUT.relative_to(ROOT)}")
    return 0


sys.exit(main())
